async function cdqTelechargerPdfClientV2268(state){
  cdqPdfProgressV2268(state.requestId,8,'Lecture des informations du PDF…');
  const meta=await cdqV19Gs('obtenirMetaDocumentPdfCDQ',[state.id]);
  const taille=Number(meta&&meta.taille||0);
  const total=Number(meta&&meta.chunks||0);
  if(!meta||taille<5||taille>32*1024*1024||!Number.isInteger(total)||total<1||total>64)
    throw new Error('Informations du PDF invalides.');

  const cacheKey=String(state.id)+'|'+String(meta.revision||'');
  const cached=cdqPdfBlobCacheV2268.get(cacheKey);
  if(cached instanceof Blob && cached.size===taille){
    cdqPdfProgressV2268(state.requestId,96,'PDF déjà prêt sur cet appareil.');
    return Object.assign({},meta,{blob:cached});
  }

  const parts=new Array(total);
  const groupSize=4;
  let done=0;

  for(let start=0;start<total;start+=groupSize){
    const lot=await cdqV19Gs('obtenirLotDocumentPdfCDQV2268',[state.id,meta.revision,start,groupSize]);
    if(!lot||String(lot.revision)!==String(meta.revision)||!Array.isArray(lot.chunks))
      throw new Error('Réponse PDF incomplète.');

    lot.chunks.forEach(function(part){
      const index=Number(part&&part.index);
      if(!Number.isInteger(index)||index<0||index>=total||!part.base64)
        throw new Error('Bloc PDF invalide.');
      parts[index]=cdqV2112Base64ToBytes(part.base64);
      done++;
    });

    cdqPdfProgressV2268(
      state.requestId,
      12+Math.round((done/total)*78),
      'Chargement du PDF · '+done+' / '+total
    );
  }

  if(parts.some(function(x){return !(x instanceof Uint8Array);}))
    throw new Error('Le PDF n’a pas été reçu au complet.');

  cdqPdfProgressV2268(state.requestId,92,'Assemblage du PDF…');
  const blob=new Blob(parts,{type:'application/pdf'});
  if(blob.size!==taille || (await blob.slice(0,5).text())!=='%PDF-')
    throw new Error('PDF incomplet. Réessayez.');

  cdqPdfBlobCacheV2268.set(cacheKey,blob);
  cdqPdfProgressV2268(state.requestId,97,'PDF prêt.');
  return Object.assign({},meta,{blob:blob});
}

function cdqDemanderComptePdfV2268(id){
  const meta=cdqDocumentMeta(id)||{};
  const requestId='pdf-'+crypto.randomUUID();
  const state={
    requestId:requestId,
    id:String(id),
    name:String(meta.nom||'Rapport.pdf'),
    reader:cdqPdfReaderPreference(),
    blob:null,
    email:''
  };
  cdqPdfOpenRequestsV2268.set(requestId,state);
  afficherMessage('Choisissez le compte Google pour ouvrir le PDF.',true);

  cdqApiRun()
    .withSuccessHandler(function(defi){
      if(!defi||!defi.challengeId||!defi.nonce||!defi.clientId){
        cdqPdfOpenRequestsV2268.delete(requestId);
        cdqPdfErrorV2268(requestId,new Error('Impossible de préparer le choix du compte Google.'));
        return;
      }
      cdqPostToPwa({
        type:'CDQ_PDF_ACCOUNT_REQUIRED_V2268',
        requestId:requestId,
        fileId:state.id,
        name:state.name,
        reader:state.reader,
        challengeId:String(defi.challengeId),
        nonce:String(defi.nonce),
        clientId:String(defi.clientId),
        expiresAt:Number(defi.expiresAt)||0
      });
    })
    .withFailureHandler(function(e){
      cdqPdfOpenRequestsV2268.delete(requestId);
      cdqPdfErrorV2268(requestId,e);
    })
    .creerDefiConnexionGoogleCDQ();
}

window.addEventListener('message',function(e){
  if(!cdqFromPwa(e))return;
  const d=e.data||{};

  if(d.type==='CDQ_PDF_ACCOUNT_CANCEL_V2268'){
    cdqPdfOpenRequestsV2268.delete(String(d.requestId||''));
    return;
  }

  if(d.type==='CDQ_PDF_ACCOUNT_CREDENTIAL_V2268'){
    const requestId=String(d.requestId||'');
    const state=cdqPdfOpenRequestsV2268.get(requestId);
    if(!state||!d.credential||!d.challengeId)return;

    cdqPdfProgressV2268(requestId,4,'Vérification du compte Google…');
    cdqApiRun()
      .withSuccessHandler(async function(resultat){
        try{
          if(!resultat||!resultat.ok)throw new Error('Google n’a pas confirmé ce compte.');
          state.email=String(resultat.email||'');
          cdqMarquerPdfOuvertV2268(state.id);
          const rec=await cdqTelechargerPdfClientV2268(state);
          state.blob=rec.blob;
          state.name=String(rec.nom||state.name||'Rapport.pdf');
          cdqPostToPwa({
            type:'CDQ_PDF_READY_V2268',
            requestId:requestId,
            fileId:state.id,
            name:state.name,
            reader:state.reader,
            email:state.email,
            blob:state.blob,
            readOnly:String(utilisateurCourantRole||'')==='lecture'
          });
        }catch(err){
          cdqPdfOpenRequestsV2268.delete(requestId);
          cdqPdfErrorV2268(requestId,err);
        }
      })
      .withFailureHandler(function(err){
        cdqPdfOpenRequestsV2268.delete(requestId);
        cdqPdfErrorV2268(requestId,err);
      })
      .verifierJetonGoogleCDQ(String(d.credential),String(d.challengeId));
    return;
  }

  if(d.type==='CDQ_PDF_OPEN_INTERNAL_V2268'){
    const requestId=String(d.requestId||'');
    const state=cdqPdfOpenRequestsV2268.get(requestId);
    if(!state||!(state.blob instanceof Blob))return;
    const rec={id:state.id,nom:state.name,blob:state.blob,taille:state.blob.size};
    cdqPdfOpenRequestsV2268.delete(requestId);
    cdqOpenPdfInternal(state.id,rec).catch(afficherErreur);
    return;
  }

  if(d.type==='CDQ_PDF_EXTERNAL_DONE_V2268'){
    cdqPdfOpenRequestsV2268.delete(String(d.requestId||''));
  }
});

const cdqV19OldModify=window.modifierFichier;
window.modifierFichier=function(id){
  const meta=cdqDocumentMeta(id);

  if(meta&&meta.type==='GOOGLE_SHEETS'){
    cdqV19OpenOfflineSheet(id);
